(function(){document.querySelectorAll(".bb-people__filter").forEach((filter)=>{const section=filter.closest(".bb-people");const chips=Array.from(filter.querySelectorAll("button"));const people=Array.from(section.querySelectorAll(".bb-people__list > li"));chips.forEach((chip)=>{chip.addEventListener("click",()=>{const sport=chip.dataset.sport;chips.forEach((c)=>c.setAttribute("aria-pressed",c===chip?"true":"false"));people.forEach((person)=>{person.hidden=sport!==""&&!person.dataset.sports.split(" ").includes(sport);});});});});})();(function(){document.querySelectorAll(".bb-people__switch").forEach((switcher)=>{const section=switcher.closest(".bb-people");const options=Array.from(switcher.querySelectorAll(".bb-switch__option"));const thumb=switcher.querySelector(".bb-switch__thumb");const people=Array.from(section.querySelectorAll(".bb-people__list > li"));function placeThumb(){const pressed=options.find((option)=>"true"===option.getAttribute("aria-pressed"));if(pressed){thumb.style.setProperty("--x",pressed.offsetLeft+"px");thumb.style.setProperty("--w",pressed.offsetWidth+"px");}}
function choose(option){options.forEach((o)=>o.setAttribute("aria-pressed",o===option?"true":"false"));people.forEach((person)=>{person.hidden=""!==option.dataset.group&&person.dataset.group!==option.dataset.group;});placeThumb();}
const fromAddress=()=>{const option=options.find((o)=>o.id&&"#"+o.id===window.location.hash);if(option){choose(option);}};options.forEach((option)=>option.addEventListener("click",()=>choose(option)));window.addEventListener("hashchange",fromAddress);fromAddress();placeThumb();window.requestAnimationFrame(()=>switcher.classList.add("is-ready"));new ResizeObserver(placeThumb).observe(switcher);});})();(function(){const still=window.matchMedia("(prefers-reduced-motion: reduce)");document.querySelectorAll(".bb-people").forEach((section)=>{const list=section.querySelector(".bb-people__list");const arrows=section.querySelector(".bb-people__arrows");if(!list||!arrows){return;}
const[back,on]=Array.from(arrows.querySelectorAll(".bb-people__arrow"));const track=arrows.querySelector(".bb-people__track");const thumb=arrows.querySelector(".bb-people__thumb");function update(){const room=list.scrollWidth-list.clientWidth;arrows.hidden=room<=2;back.disabled=list.scrollLeft<=2;on.disabled=list.scrollLeft>=room-2;if(track&&thumb&&room>2){const share=list.clientWidth/list.scrollWidth;const width=track.clientWidth*share;thumb.style.setProperty("--w",width+"px");thumb.style.setProperty("--x",(track.clientWidth-width)*Math.min(1,list.scrollLeft/room)+"px",);}}
const step=()=>{const card=Array.from(list.children).find((li)=>!li.hidden);const gap=parseFloat(getComputedStyle(list).columnGap)||0;return card?card.getBoundingClientRect().width+gap:list.clientWidth;};arrows.querySelectorAll(".bb-people__arrow").forEach((arrow)=>arrow.addEventListener("click",()=>list.scrollBy({left:Number(arrow.dataset.step)*step(),behavior:still.matches?"auto":"smooth",}),),);list.addEventListener("scroll",update,{passive:true});new ResizeObserver(update).observe(list);section.querySelectorAll(".bb-switch__option, .bb-people__filter button").forEach((choice)=>choice.addEventListener("click",()=>{list.scrollLeft=0;window.requestAnimationFrame(update);}),);update();});})();